{
  "name": "Cobolt 激光器",
  "name_en": "Cobolt Laser",
  "manufacturer": "Cobolt",
  "description": "Cobolt 激光器是一种实验室用紧凑型激光光源，可提供稳定的连续激光输出，常用于光学实验、光路搭建、对准以及荧光等测量应用。",
  "description_en": "A Cobolt laser is a compact laboratory laser source that provides stable continuous-wave laser output, commonly used for optical experiments, beam alignment, optical setups, and fluorescence-related measurements.",
  "tag_hints": [
    "laser source",
    "continuous-wave laser",
    "optical alignment",
    "fluorescence excitation",
    "beam power control"
  ],
  "actions": [
    {
      "action_name": "auto-setPower",
      "description": "设置激光输出功率。",
      "description_en": "Set the laser output power."
    },
    {
      "action_name": "auto-power",
      "description": "获取激光输出功率。",
      "description_en": "Get the laser output power."
    }
  ]
}

